//! Rust host infrastructure for the exact recovered QML bundle.
//! Native module implementation and original application startup remain separate.

use cxx_qt_lib::{QGuiApplication, QQmlApplicationEngine, QString, QUrl};
use std::sync::{
    Arc,
    atomic::{AtomicU8, Ordering},
};

pub const ORIGINAL_MAIN: &str = "qrc:/qml/Main.qml";
pub const ORIGINAL_IMPORT_ROOT: &str = "qrc:/";

/// Register the unchanged resource collection generated by Qt's rcc.
pub fn initialize_resources() {
    cxx_qt::init_crate!(original_qml_host);
}

/// Independent launcher policy: fail if the local root cannot be created.
/// Call `register_types` before the engine is constructed.
pub fn run(check_only: bool, register_types: impl FnOnce() -> Result<(), String>) -> i32 {
    let mut app = QGuiApplication::new();
    if app.is_null() {
        eprintln!("QGuiApplication construction failed");
        return 1;
    }
    initialize_resources();
    let registered = match register_types() {
        Ok(()) => true,
        Err(error) => {
            eprintln!("Original native type registration failed: {error}");
            if !check_only {
                return 1;
            }
            false
        }
    };
    let mut engine = QQmlApplicationEngine::new();
    if engine.is_null() {
        eprintln!("QQmlApplicationEngine construction failed");
        return 1;
    }
    engine
        .pin_mut()
        .add_import_path(&QString::from(ORIGINAL_IMPORT_ROOT));
    let state = Arc::new(AtomicU8::new(0));
    let observed = Arc::clone(&state);
    let _created = engine.pin_mut().on_object_created(move |_, object, _| {
        observed.store(if object.is_null() { 2 } else { 1 }, Ordering::Release);
    });
    engine.pin_mut().load(&QUrl::from(ORIGINAL_MAIN));
    // Qt loads qrc URLs synchronously. Keep the engine and connection alive.
    if state.load(Ordering::Acquire) != 1 {
        eprintln!("Original QML root creation failed: {ORIGINAL_MAIN}");
        return 1;
    }
    if check_only {
        i32::from(!registered)
    } else {
        app.pin_mut().exec()
    }
}
